package demo;

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import java.io.IOException;
import java.io.InputStream;

// Case invocation-02.
// Deliberately vulnerable synthetic subprocess; no network or real targets.
public class DemoService {
    public String lookup(String input) throws Exception {
        boolean windows = System.getProperty("os.name").toLowerCase().contains("win");
        String java = Path.of(System.getProperty("java.home"), "bin", windows ? "java.exe" : "java").toString();
        String flag = windows ? "/c" : "-c";
        String invocation = "echo echo:" + input;
        ProcessBuilder child = new ProcessBuilder(java, flag, invocation).redirectErrorStream(true);
        try {
            Process process = child.start();
            if (!process.waitFor(5, TimeUnit.SECONDS)) { process.destroyForcibly(); throw new IllegalStateException("child timeout"); }
            if (process.exitValue() != 0) throw new IllegalStateException("child failed");
            InputStream inputStream = process.getInputStream(); 
            return new String(inputStream.readAllBytes(), StandardCharsets.UTF_8).trim();
        } catch (IOException | InterruptedException e) {
            throw new Exception("Error executing process", e);
        }
    }
}

